  }

  await pnpmInstall();

  // Order is load-bearing, see composeCreateArgs: create (network exists) -> attach the proxy
  // (the public names resolve inside the network) -> start and wait for health.
  await compose(instance, composeCreateArgs(options));
  await attachInstance({ repoRoot: REPO_ROOT, instance, exec: run });
  await startAndWait(instance, options);

  if (needsSeed) {
    // `needsSeed` means Keycloak's database was either just wiped (`--fresh`) or has never finished
    // a `just up` before — in both cases the container that just went healthy in `startAndWait`
    // above imported the realm we rendered for real, so this is the one moment recording it is
    // actually true. This runs regardless of `--no-seed`: the realm import is Keycloak's business,
    // entirely independent of whether the *app's* sample data gets seeded below.
    writeRealmHash(instance, renderedRealm);

    if (options.seed) {
      console.log('\nSeeding sample data…');
      // --force-recreate because this is a one-shot job, not a service: a leftover container from
      // an earlier run holds that run's network id, and after `just reset` recreated the network
      // compose would try to *start* the stale one and fail with "network ... not found". Observed
      // in a real cold-start cycle. Recreating a container that is meant to run once and exit
      // costs nothing.
      await compose(instance, seedArgs());
      writeFileSync(seededMarker, `${new Date().toISOString()}\n`);
    } else {
      console.log(
        '\nSkipping seeding (--no-seed). The database is not seeded yet — run `just up` ' +
          '(without --no-seed) to seed it.',
      );
    }
  } else {
    console.log('\nReusing the existing database. `just up --fresh` wipes and re-seeds.');
  }

  console.log(`\nURLs\n${urlTable(instance, proxyPort)}`);
  const dbPort = await postgresHostPort(instance, run);
  if (dbPort === null) {
    console.log('\nPostgres\n  unavailable');
  } else {
    console.log(`\nPostgres\n${postgresHint(dbPort)}`);
  }

  if (options.detach) {
    console.log('\nDev servers not started (--detach). Run `just serve` to start them.');
    return 0;
  } else {
    console.log('\nStarting dev servers. Ctrl-C stops all of them.\n');
    const handle = await startDevServers({
      repoRoot: REPO_ROOT,
      instance,
      ports,
      selection: options.apps,
      spawnProcess: spawnResolved,
    });
    // If one dev server dies on its own, `just up` must not sit there looking healthy with two of
    // three running, nor exit 0 as if it had been a clean Ctrl-C — `finishDevServers` races the
    // crash against the signals and reports whichever one actually happened.
    return await finishDevServers({ handle });
  }
}

async function askTerminal(question, fallback) {
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  try {
    return await rl.question(`${question} [${fallback}]: `);
  } finally {
    rl.close();
  }
}

async function pnpmInstall() {
  console.log('\nInstalling frontend dependencies…');
  const result = await runInherited('pnpm', ['install'], { cwd: join(REPO_ROOT, 'app') });
  if (result !== 0) {
    throw new Error(`pnpm install failed with exit code ${result}.`);
  }
}

